        "file_path": "/private/tmp/rp1-evals/f21bc400/workspace/src/yaml-parser.ts",
        "content": "/**\n * YAML syntax validation engine.\n *\n * Provides a line-by-line state machine parser that checks whether YAML\n * content is syntactically well-formed. Covers basic YAML: block mappings,\n * block sequences, scalars, quoted strings, comments, multi-line scalars,\n * flow collections, document markers, anchors, and aliases.\n */\n\n/** Result of YAML syntax validation. */\nexport interface YamlValidationResult {\n  /** Whether the YAML content is syntactically valid. */\n  valid: boolean;\n  /** Error details, present only when valid is false. */\n  error?: {\n    /** Human-readable description of the syntax problem. */\n    message: string;\n    /** 1-based line number where the error was detected. */\n    line: number;\n    /** 1-based column number where the error was detected (when available). */\n    column?: number;\n  };\n}\n\ninterface ParserState {\n  indentStack: number[];\n  inMultiLineScalar: boolean;\n  multiLineIndent: number;\n  flowDepth: number;\n  lineNumber: number;\n}\n\nfunction makeError(\n  message: string,\n  line: number,\n  column?: number,\n): YamlValidationResult {\n  const error: YamlValidationResult[\"error\"] = { message, line };\n  if (column !== undefined) {\n    error.column = column;\n  }\n  return { valid: false, error };\n}\n\n/**\n * Strip an inline comment from a line, respecting quoted strings.\n * Returns the content portion without the trailing comment.\n */\nfunction stripInlineComment(line: string): string {\n  let inSingle = false;\n  let inDouble = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < line.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') {\n        inDouble = false;\n      }\n      continue;\n    }\n\n    if (inSingle) {\n      if (ch === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") {\n        inSingle = false;\n      }\n      continue;\n    }\n\n    if (ch === '\"') {\n      inDouble = true;\n      continue;\n    }\n    if (ch === \"'\") {\n      inSingle = true;\n      continue;\n    }\n\n    if (ch === \"#\" && (i === 0 || line[i - 1] === \" \" || line[i - 1] === \"\\t\")) {\n      return line.slice(0, i).trimEnd();\n    }\n  }\n\n  return line;\n}\n\n/**\n * Check whether quotes are balanced on a line. Returns an error message\n * if an unterminated quoted string is found, or null if balanced.\n */\nfunction checkQuoteBalance(\n  line: string,\n): { message: string; column: number } | null {\n  let i = 0;\n\n  while (i < line.length) {\n    const ch = line[i];\n\n    if (ch === '\"') {\n      const start = i;\n      i++;\n      while (i < line.length) {\n        if (line[i] === \"\\\\\" && i + 1 < line.length) {\n          i += 2;\n          continue;\n        }\n        if (line[i] === '\"') {\n          break;\n        }\n        i++;\n      }\n      if (i >= line.length) {\n        return {\n          message: \"Unterminated quoted string\",\n          column: start + 1,\n        };\n      }\n      i++;\n      continue;\n    }\n\n    if (ch === \"'\") {\n      const start = i;\n      i++;\n      while (i < line.length) {\n        if (line[i] === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n          i += 2;\n          continue;\n        }\n        if (line[i] === \"'\") {\n          break;\n        }\n        i++;\n      }\n      if (i >= line.length) {\n        return {\n          message: \"Unterminated quoted string\",\n          column: start + 1,\n        };\n      }\n      i++;\n      continue;\n    }\n\n    if (ch === \"#\" && (i === 0 || line[i - 1] === \" \" || line[i - 1] === \"\\t\")) {\n      break;\n    }\n\n    i++;\n  }\n\n  return null;\n}\n\n/**\n * Count leading spaces on a line. Returns the number of space characters\n * at the start.\n */\nfunction leadingSpaces(line: string): number {\n  let count = 0;\n  while (count < line.length && line[count] === \" \") {\n    count++;\n  }\n  return count;\n}\n\n/**\n * Check if a line is a full-line comment (optional leading spaces then #).\n */\nfunction isCommentLine(trimmed: string): boolean {\n  return trimmed.startsWith(\"#\");\n}\n\n/**\n * Check if a line is a document marker (--- or ...).\n */\nfunction isDocumentMarker(line: string): boolean {\n  const trimmed = line.trimEnd();\n  return (\n    (trimmed === \"---\" || trimmed === \"...\") &&\n    leadingSpaces(line) === 0\n  );\n}\n\n/**\n * Check if a line is a YAML directive (%YAML or %TAG).\n */\nfunction isDirective(trimmed: string): boolean {\n  return trimmed.startsWith(\"%YAML\") || trimmed.startsWith(\"%TAG\");\n}\n\n/**\n * Update flow depth based on flow collection characters on a line.\n * Returns the new depth or an error.\n */\nfunction updateFlowDepth(\n  line: string,\n  currentDepth: number,\n  lineNumber: number,\n): { depth: number; error?: YamlValidationResult } {\n  let depth = currentDepth;\n  let inSingle = false;\n  let inDouble = false;\n\n  for (let i = 0; i < line.length; i++) {\n    const ch = line[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < line.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') {\n        inDouble = false;\n      }\n      continue;\n    }\n\n    if (inSingle) {\n      if (ch === \"'\" && i + 1 < line.length && line[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") {\n        inSingle = false;\n      }\n      continue;\n    }\n\n    if (ch === '\"') {\n      inDouble = true;\n      continue;\n    }\n    if (ch === \"'\") {\n      inSingle = true;\n      continue;\n    }\n\n    if (ch === \"#\" && (i === 0 || line[i - 1] === \" \" || line[i - 1] === \"\\t\")) {\n      break;\n    }\n\n    if (ch === \"{\" || ch === \"[\") {\n      depth++;\n    } else if (ch === \"}\" || ch === \"]\") {\n      depth--;\n      if (depth < 0) {\n        return {\n          depth,\n          error: makeError(\"Unexpected closing bracket\", lineNumber, i + 1),\n        };\n      }\n    }\n  }\n\n  return { depth };\n}\n\n/**\n * Check if a value portion indicates a multi-line scalar (|, >, |+, |-, >+, >-).\n */\nfunction isMultiLineScalarIndicator(value: string): boolean {\n  const trimmed = value.trim();\n  return /^[|>][+-]?$/.test(trimmed);\n}\n\n/**\n * Validate YAML content for syntactic correctness.\n *\n * Parses the input string line by line using a state machine and reports\n * whether the content is syntactically valid YAML.\n */\nexport function validateYaml(content: string): YamlValidationResult {\n  if (content.length === 0) {\n    return { valid: true };\n  }\n\n  const lines = content.split(\"\\n\");\n  const state: ParserState = {\n    indentStack: [0],\n    inMultiLineScalar: false,\n    multiLineIndent: 0,\n    flowDepth: 0,\n    lineNumber: 0,\n  };\n\n  for (let i = 0; i < lines.length; i++) {\n    state.lineNumber = i + 1;\n    const rawLine = lines[i];\n\n    if (rawLine.length === 0 || rawLine.trim().length === 0) {\n      continue;\n    }\n\n    const hasTab =\n      rawLine.length > 0 &&\n      leadingSpaces(rawLine) < rawLine.length &&\n      rawLine.slice(0, rawLine.length - rawLine.trimStart().length).includes(\"\\t\");\n\n    if (hasTab) {\n      const tabIndex = rawLine.indexOf(\"\\t\");\n      return makeError(\n        \"Tab characters are not allowed for indentation in YAML\",\n        state.lineNumber,\n        tabIndex + 1,\n      );\n    }\n\n    const trimmed = rawLine.trim();\n\n    if (state.inMultiLineScalar) {\n      if (trimmed.length === 0) {\n        continue;\n      }\n\n      const indent = leadingSpaces(rawLine);\n\n      if (indent > state.multiLineIndent || (indent === state.multiLineIndent && state.multiLineIndent > 0)) {\n        continue;\n      }\n\n      state.inMultiLineScalar = false;\n    }\n\n    if (isCommentLine(trimmed)) {\n      continue;\n    }\n\n    if (isDirective(trimmed)) {\n      continue;\n    }\n\n    if (isDocumentMarker(rawLine)) {\n      state.indentStack = [0];\n      state.inMultiLineScalar = false;\n      state.flowDepth = 0;\n      continue;\n    }\n\n    const quoteError = checkQuoteBalance(trimmed);\n    if (quoteError) {\n      return makeError(\n        quoteError.message,\n        state.lineNumber,\n        quoteError.column,\n      );\n    }\n\n    const flowResult = updateFlowDepth(\n      trimmed,\n      state.flowDepth,\n      state.lineNumber,\n    );\n    if (flowResult.error) {\n      return flowResult.error;\n    }\n    state.flowDepth = flowResult.depth;\n\n    if (state.flowDepth > 0) {\n      continue;\n    }\n\n    const indent = leadingSpaces(rawLine);\n    const contentAfterIndent = stripInlineComment(trimmed);\n\n    if (contentAfterIndent.length === 0) {\n      continue;\n    }\n\n    const currentIndent = state.indentStack[state.indentStack.length - 1];\n\n    if (indent > currentIndent) {\n      state.indentStack.push(indent);\n    } else if (indent < currentIndent) {\n      let found = false;\n      while (state.indentStack.length > 1) {\n        state.indentStack.pop();\n        if (state.indentStack[state.indentStack.length - 1] === indent) {\n          found = true;\n          break;\n        }\n        if (state.indentStack[state.indentStack.length - 1] < indent) {\n          break;\n        }\n      }\n      if (!found && indent !== 0) {\n        return makeError(\n          `Invalid indentation: expected ${state.indentStack[state.indentStack.length - 1]} spaces, found ${indent}`,\n          state.lineNumber,\n          indent + 1,\n        );\n      }\n      if (indent === 0) {\n        state.indentStack = [0];\n      }\n    }\n\n    if (contentAfterIndent.startsWith(\"- \") || contentAfterIndent === \"-\") {\n      const afterDash = contentAfterIndent.slice(2).trim();\n      if (afterDash.length > 0) {\n        const colonIndex = findMappingColon(afterDash);\n        if (colonIndex !== -1) {\n          const value = afterDash.slice(colonIndex + 1).trim();\n          if (isMultiLineScalarIndicator(value)) {\n            state.inMultiLineScalar = true;\n            state.multiLineIndent = indent;\n          }\n        }\n      }\n      continue;\n    }\n\n    if (contentAfterIndent.startsWith(\"&\") || contentAfterIndent.startsWith(\"*\")) {\n      continue;\n    }\n\n    if (\n      contentAfterIndent.startsWith(\"{\") ||\n      contentAfterIndent.startsWith(\"[\")\n    ) {\n      continue;\n    }\n\n    const colonIndex = findMappingColon(contentAfterIndent);\n\n    if (colonIndex !== -1) {\n      const value = contentAfterIndent.slice(colonIndex + 1).trim();\n      if (isMultiLineScalarIndicator(value)) {\n        state.inMultiLineScalar = true;\n        state.multiLineIndent = indent;\n      }\n      continue;\n    }\n\n    if (\n      contentAfterIndent.startsWith('\"') ||\n      contentAfterIndent.startsWith(\"'\") ||\n      isPlainScalar(contentAfterIndent)\n    ) {\n      continue;\n    }\n\n    continue;\n  }\n\n  if (state.flowDepth > 0) {\n    return makeError(\"Unclosed flow collection\", state.lineNumber);\n  }\n\n  return { valid: true };\n}\n\n/**\n * Find the colon that separates a mapping key from its value.\n * The colon must be followed by a space, end of string, or precede\n * a flow/multiline indicator. Returns the index of the colon or -1.\n */\nfunction findMappingColon(content: string): number {\n  let inSingle = false;\n  let inDouble = false;\n\n  for (let i = 0; i < content.length; i++) {\n    const ch = content[i];\n\n    if (inDouble) {\n      if (ch === \"\\\\\" && i + 1 < content.length) {\n        i++;\n        continue;\n      }\n      if (ch === '\"') {\n        inDouble = false;\n      }\n      continue;\n    }\n\n    if (inSingle) {\n      if (ch === \"'\" && i + 1 < content.length && content[i + 1] === \"'\") {\n        i++;\n        continue;\n      }\n      if (ch === \"'\") {\n        inSingle = false;\n      }\n      continue;\n    }\n\n    if (ch === '\"') {\n      inDouble = true;\n      continue;\n    }\n    if (ch === \"'\") {\n      inSingle = true;\n      continue;\n    }\n\n    if (ch === \"#\" && (i === 0 || content[i - 1] === \" \")) {\n      break;\n    }\n\n    if (\n      ch === \":\" &&\n      (i + 1 >= content.length || content[i + 1] === \" \" || content[i + 1] === \"\\t\")\n    ) {\n      return i;\n    }\n  }\n\n  return -1;\n}\n\n/**\n * Check if a string looks like a valid plain (unquoted) scalar value.\n */\nfunction isPlainScalar(value: string): boolean {\n  if (value.length === 0) {\n    return false;\n  }\n  const firstChar = value[0];\n  if (firstChar === \" \" || firstChar === \"\\t\") {\n    return false;\n  }\n  return true;\n}\n"
