        "file_path": "/private/tmp/rp1-evals/f21bc400/workspace/src/validate-yaml.ts",
        "content": "/**\n * YAML validation CLI command.\n *\n * Entry point for `bun run validate`. Accepts a single YAML file path,\n * reads the file, validates its syntax using the YAML parser engine,\n * and reports the result with appropriate exit codes.\n */\n\nimport { resolve } from \"node:path\";\nimport { validateYaml } from \"./yaml-parser\";\n\nasync function main(): Promise<void> {\n  const filePath = process.argv[2];\n\n  if (!filePath) {\n    console.error(\"Usage: bun run validate <file.yaml>\");\n    process.exit(1);\n  }\n\n  const resolvedPath = resolve(filePath);\n  const file = Bun.file(resolvedPath);\n\n  const exists = await file.exists();\n  if (!exists) {\n    console.error(`Error: File not found - ${resolvedPath}`);\n    process.exit(1);\n  }\n\n  let content: string;\n  try {\n    content = await file.text();\n  } catch {\n    console.error(`Error: Cannot read file - ${resolvedPath}`);\n    process.exit(1);\n  }\n\n  const result = validateYaml(content);\n\n  if (result.valid) {\n    console.log(`Valid YAML: ${resolvedPath}`);\n    process.exit(0);\n  }\n\n  const error = result.error!;\n  const location =\n    error.column !== undefined\n      ? `line ${error.line}, column ${error.column}`\n      : `line ${error.line}`;\n\n  console.error(`Invalid YAML: ${resolvedPath}`);\n  console.error(`  Error on ${location}: ${error.message}`);\n  process.exit(1);\n}\n\nmain();\n"
      },
