import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-parser";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple key-value mapping", () => {
      const result = validateYaml("name: Alice\nage: 30");
      expect(result.valid).toBe(true);
    });

    test("nested mappings", () => {
      const yaml = [
        "server:",
        "  host: localhost",
        "  port: 8080",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("deeply nested mappings", () => {
      const yaml = [
        "level1:",
        "  level2:",
        "    level3:",
        "      key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("simple sequence", () => {
      const yaml = [
        "- apple",
        "- banana",
        "- cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("nested sequence within mapping", () => {
      const yaml = [
        "fruits:",
        "  - apple",
        "  - banana",
        "  - cherry",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("sequence of mappings", () => {
      const yaml = [
        "- name: Alice",
        "  age: 30",
        "- name: Bob",
        "  age: 25",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("inline comment", () => {
      const result = validateYaml("key: value # this is a comment");
      expect(result.valid).toBe(true);
    });

    test("full-line comment", () => {
      const yaml = [
        "# This is a comment",
        "key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("empty string", () => {
      const result = validateYaml("");
      expect(result.valid).toBe(true);
    });

    test("whitespace-only content", () => {
      const result = validateYaml("   \n  \n    ");
      expect(result.valid).toBe(true);
    });

    test("comment-only content", () => {
      const yaml = [
        "# comment line 1",
        "# comment line 2",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("single-quoted strings", () => {
      const result = validateYaml("name: 'Alice'");
      expect(result.valid).toBe(true);
    });

    test("double-quoted strings", () => {
      const result = validateYaml('name: "Alice"');
      expect(result.valid).toBe(true);
    });

    test("double-quoted string with escaped quotes", () => {
      const result = validateYaml('greeting: "say \\"hello\\""');
      expect(result.valid).toBe(true);
    });

    test("single-quoted string with escaped single quote", () => {
      const result = validateYaml("name: 'it''s fine'");
      expect(result.valid).toBe(true);
    });

    test("literal block scalar", () => {
      const yaml = [
        "description: |",
        "  This is line one.",
        "  This is line two.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("folded block scalar", () => {
      const yaml = [
        "description: >",
        "  This is a long",
        "  paragraph that folds.",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("literal block scalar with chomping modifier", () => {
      const yaml = [
        "text: |-",
        "  no trailing newline",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("flow mapping", () => {
      const result = validateYaml("{name: Alice, age: 30}");
      expect(result.valid).toBe(true);
    });

    test("flow sequence", () => {
      const result = validateYaml("[apple, banana, cherry]");
      expect(result.valid).toBe(true);
    });

    test("nested flow collections", () => {
      const result = validateYaml("{users: [{name: Alice}, {name: Bob}]}");
      expect(result.valid).toBe(true);
    });

    test("document start marker", () => {
      const yaml = [
        "---",
        "key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("document end marker", () => {
      const yaml = [
        "key: value",
        "...",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("multiple documents", () => {
      const yaml = [
        "---",
        "doc: one",
        "---",
        "doc: two",
        "...",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("boolean and null values", () => {
      const yaml = [
        "enabled: true",
        "disabled: false",
        "empty: null",
        "also_empty: ~",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("anchor definition", () => {
      const result = validateYaml("&defaults");
      expect(result.valid).toBe(true);
    });

    test("alias reference", () => {
      const result = validateYaml("*defaults");
      expect(result.valid).toBe(true);
    });

    test("anchor and alias in mappings", () => {
      const yaml = [
        "defaults: &defaults",
        "  timeout: 30",
        "production:",
        "  *defaults",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("YAML directive", () => {
      const yaml = [
        "%YAML 1.2",
        "---",
        "key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("blank lines between entries", () => {
      const yaml = [
        "key1: value1",
        "",
        "key2: value2",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("mapping value with colon in quoted string", () => {
      const result = validateYaml('url: "http://example.com:8080"');
      expect(result.valid).toBe(true);
    });

    test("multi-line flow collection", () => {
      const yaml = [
        "{",
        "  name: Alice,",
        "  age: 30",
        "}",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });

    test("mixed mappings and sequences", () => {
      const yaml = [
        "users:",
        "  - name: Alice",
        "    roles:",
        "      - admin",
        "      - user",
        "  - name: Bob",
        "    roles:",
        "      - user",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML", () => {
    test("tab indentation", () => {
      const yaml = "key:\n\tvalue: bad";
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(2);
      expect(result.error!.message).toContain("Tab");
    });

    test("tab indentation on first line", () => {
      const result = validateYaml("\tkey: value");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Tab");
    });

    test("unterminated double quote", () => {
      const result = validateYaml('key: "unclosed');
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unterminated quoted string");
    });

    test("unterminated single quote", () => {
      const result = validateYaml("key: 'unclosed");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unterminated quoted string");
    });

    test("unclosed flow mapping", () => {
      const result = validateYaml("{key: value");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unclosed flow collection");
    });

    test("unclosed flow sequence", () => {
      const result = validateYaml("[item1, item2");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unclosed flow collection");
    });

    test("extra closing brace", () => {
      const result = validateYaml("key: value}");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unexpected closing bracket");
    });

    test("extra closing bracket", () => {
      const result = validateYaml("key: value]");
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(1);
      expect(result.error!.message).toContain("Unexpected closing bracket");
    });

    test("bad indentation decreasing to non-ancestor level", () => {
      const yaml = [
        "key:",
        "    nested: value",
        "  bad: indent",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(3);
      expect(result.error!.message).toContain("Invalid indentation");
    });

    test("unterminated double quote on later line", () => {
      const yaml = [
        "name: Alice",
        'title: "unclosed',
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.line).toBe(2);
      expect(result.error!.message).toContain("Unterminated quoted string");
    });

    test("unclosed flow mapping on later line", () => {
      const yaml = [
        "name: Alice",
        "data: {key: value",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error).toBeDefined();
      expect(result.error!.message).toContain("Unclosed flow collection");
    });
  });

  describe("error line number accuracy", () => {
    test("reports correct line for tab on line 3", () => {
      const yaml = [
        "key1: value1",
        "key2: value2",
        "\tbad: tabs",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error!.line).toBe(3);
    });

    test("reports correct line for unterminated quote on line 4", () => {
      const yaml = [
        "a: 1",
        "b: 2",
        "c: 3",
        "d: 'oops",
      ].join("\n");
      const result = validateYaml(yaml);
      expect(result.valid).toBe(false);
      expect(result.error!.line).toBe(4);
    });

    test("includes column info for unterminated quote", () => {
      const result = validateYaml('key: "unclosed');
      expect(result.valid).toBe(false);
      expect(result.error!.column).toBeDefined();
      expect(result.error!.column).toBeGreaterThan(0);
    });

    test("includes column info for tab character", () => {
      const result = validateYaml("\tkey: value");
      expect(result.valid).toBe(false);
      expect(result.error!.column).toBeDefined();
      expect(result.error!.column).toBe(1);
    });
  });
});

import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { mkdtemp, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

const CLI_PATH = join(import.meta.dir, "validate-yaml.ts");

async function runCli(
  ...args: string[]
): Promise<{ stdout: string; stderr: string; exitCode: number }> {
  const proc = Bun.spawn(["bun", CLI_PATH, ...args], {
    stdout: "pipe",
    stderr: "pipe",
  });

  const [stdout, stderr] = await Promise.all([
    new Response(proc.stdout).text(),
    new Response(proc.stderr).text(),
  ]);

  const exitCode = await proc.exited;

  return { stdout, stderr, exitCode };
}

describe("validate-yaml CLI", () => {
  let tempDir: string;
  let validFile: string;
  let invalidFile: string;
  let emptyFile: string;

  beforeAll(async () => {
    tempDir = await mkdtemp(join(tmpdir(), "yaml-cli-test-"));

    validFile = join(tempDir, "valid.yaml");
    await writeFile(validFile, "name: Alice\nage: 30\n");

    invalidFile = join(tempDir, "invalid.yaml");
    await writeFile(invalidFile, "key:\n\tbad: tabs\n");

    emptyFile = join(tempDir, "empty.yaml");
    await writeFile(emptyFile, "");
  });

  afterAll(async () => {
    await rm(tempDir, { recursive: true, force: true });
  });

  test("no arguments prints usage and exits with code 1", async () => {
    const { stdout, stderr, exitCode } = await runCli();

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Usage:");
    expect(stdout).toBe("");
  });

  test("valid YAML file prints success and exits with code 0", async () => {
    const { stdout, stderr, exitCode } = await runCli(validFile);

    expect(exitCode).toBe(0);
    expect(stdout).toContain("Valid YAML:");
    expect(stdout).toContain(validFile);
    expect(stderr).toBe("");
  });

  test("invalid YAML file prints error with line number and exits with code 1", async () => {
    const { stdout, stderr, exitCode } = await runCli(invalidFile);

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Invalid YAML:");
    expect(stderr).toMatch(/line \d+/);
    expect(stdout).toBe("");
  });

  test("nonexistent file prints file not found and exits with code 1", async () => {
    const nonexistent = join(tempDir, "does-not-exist.yaml");
    const { stdout, stderr, exitCode } = await runCli(nonexistent);

    expect(exitCode).toBe(1);
    expect(stderr).toContain("File not found");
    expect(stdout).toBe("");
  });

  test("empty YAML file prints success and exits with code 0", async () => {
    const { stdout, stderr, exitCode } = await runCli(emptyFile);

    expect(exitCode).toBe(0);
    expect(stdout).toContain("Valid YAML:");
    expect(stdout).toContain(emptyFile);
    expect(stderr).toBe("");
  });

  test("directory path prints cannot read file and exits with code 1", async () => {
    const { stdout, stderr, exitCode } = await runCli(tempDir);

    expect(exitCode).toBe(1);
    expect(stderr).toContain("Cannot read file");
    expect(stdout).toBe("");
  });

  test("valid file output includes resolved file path", async () => {
    const { stdout } = await runCli(validFile);

    expect(stdout).toContain(validFile);
  });

  test("invalid file output includes resolved file path", async () => {
    const { stderr } = await runCli(invalidFile);

    expect(stderr).toContain(invalidFile);
  });
});

