 {\n    return { valid: true, errors: [] };\n  }\n  const errors: ValidationError[] = [];\n  const allLines = content.split(\"\\n\");\n  checkControlCharacters(allLines, errors);\n  const documents = splitDocuments(allLines);\n  for (const doc of documents) {\n    validateDocument(doc, errors);\n  }\n  return { valid: errors.length === 0, errors };\n}\n```\n\n**`src/validate-yaml.ts`** (55 lines):\n```typescript\n// CLI main function (lines 17-53)\nasync function main(): Promise<void> {\n  const filePaths = process.argv.slice(2);\n  if (filePaths.length === 0) {\n    console.error(USAGE);\n    process.exit(1);\n  }\n  let hasErrors = false;\n  for (const filePath of filePaths) {\n    const file = Bun.file(filePath);\n    const exists = await file.exists();\n    if (!exists) {\n      console.error(`Error: ${filePath} - file not found`);\n      hasErrors = true;\n      continue;\n    }\n    const content = await file.text();\n    const result = validateYaml(content);\n    if (result.valid) {\n      console.log(`Valid: ${filePath}`);\n    } else {\n      for (const error of result.errors) {\n        console.error(`Error: ${filePath}:${error.line}:${error.column} - ${error.message}`);\n      }\n      hasErrors = true;\n    }\n  }\n  process.exit(hasErrors ? 1 : 0);\n}\n```\n\n**`package.json`** (no new dependencies):\n```json\n{\n  \"devDependencies\": {\n    \"@types/bun\": \"latest\"\n  }\n}\n```\n\n### Test Results\n```\nbun test v1.3.3\n 45 pass\n  0 fail\n 107 expect() calls\nRan 45 tests across 3 files. [252.00ms]\n```\n\n### Test Breakdown\n- `src/yaml-parser.test.ts`: 36 tests (all passing) -- unit tests for parser\n- `src/validate-yaml.test.ts`: 7 tests (all passing) -- CLI integration tests\n- `src/utils.test.ts`: 2 tests (all passing) -- pre-existing utility tests (no regression)\n"
