        "content": "import { describe, expect, test, afterEach } from \"bun:test\";\nimport { mkdtemp, rm } from \"node:fs/promises\";\nimport { tmpdir } from \"node:os\";\nimport { join } from \"node:path\";\n\nconst CLI_PATH = join(import.meta.dir, \"validate-yaml.ts\");\n\nasync function runCli(\n  args: string[]\n): Promise<{ stdout: string; stderr: string; exitCode: number }> {\n  const proc = Bun.spawn([\"bun\", CLI_PATH, ...args], {\n    stdout: \"pipe\",\n    stderr: \"pipe\",\n  });\n  const [stdout, stderr, exitCode] = await Promise.all([\n    new Response(proc.stdout).text(),\n    new Response(proc.stderr).text(),\n    proc.exited,\n  ]);\n  return { stdout, stderr, exitCode };\n}\n\ndescribe(\"validate-yaml CLI\", () => {\n  let tempDir: string;\n\n  async function createTempDir(): Promise<string> {\n    tempDir = await mkdtemp(join(tmpdir(), \"yaml-validator-test-\"));\n    return tempDir;\n  }\n\n  afterEach(async () => {\n    if (tempDir) {\n      await rm(tempDir, { recursive: true, force: true });\n    }\n  });\n\n  test(\"no arguments prints usage and exits with code 1\", async () => {\n    const { stdout, stderr, exitCode } = await runCli([]);\n\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"Usage:\");\n    expect(stderr).toContain(\"validate-yaml\");\n    expect(stdout).toBe(\"\");\n  });\n\n  test(\"valid YAML file prints success and exits with code 0\", async () => {\n    const dir = await createTempDir();\n    const filePath = join(dir, \"valid.yml\");\n    await Bun.write(filePath, \"name: Alice\\nage: 30\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(`Valid: ${filePath}`);\n    expect(stderr).toBe(\"\");\n  });\n\n  test(\"invalid YAML file prints error with line info and exits with code 1\", async () => {\n    const dir = await createTempDir();\n    const filePath = join(dir, \"invalid.yml\");\n    await Bun.write(filePath, 'key: \"unclosed\\n');\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(`Error: ${filePath}:`);\n    expect(stderr).toMatch(/:\\d+:\\d+ -/);\n    expect(stdout).toBe(\"\");\n  });\n\n  test(\"missing file prints file not found and exits with code 1\", async () => {\n    const missingPath = \"/tmp/yaml-validator-nonexistent-file-12345.yml\";\n\n    const { stdout, stderr, exitCode } = await runCli([missingPath]);\n\n    expect(exitCode).toBe(1);\n    expect(stderr).toContain(\"file not found\");\n    expect(stderr).toContain(missingPath);\n    expect(stdout).toBe(\"\");\n  });\n\n  test(\"multiple valid files prints success for each and exits with code 0\", async () => {\n    const dir = await createTempDir();\n    const file1 = join(dir, \"a.yml\");\n    const file2 = join(dir, \"b.yml\");\n    await Bun.write(file1, \"key1: value1\\n\");\n    await Bun.write(file2, \"key2: value2\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli([file1, file2]);\n\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(`Valid: ${file1}`);\n    expect(stdout).toContain(`Valid: ${file2}`);\n    expect(stderr).toBe(\"\");\n  });\n\n  test(\"mixed valid and invalid files reports both and exits with code 1\", async () => {\n    const dir = await createTempDir();\n    const validFile = join(dir, \"good.yml\");\n    const invalidFile = join(dir, \"bad.yml\");\n    await Bun.write(validFile, \"status: ok\\n\");\n    await Bun.write(invalidFile, \"items: [a, b\\n\");\n\n    const { stdout, stderr, exitCode } = await runCli([\n      validFile,\n      invalidFile,\n    ]);\n\n    expect(exitCode).toBe(1);\n    expect(stdout).toContain(`Valid: ${validFile}`);\n    expect(stderr).toContain(`Error: ${invalidFile}:`);\n  });\n\n  test(\"empty file is treated as valid and exits with code 0\", async () => {\n    const dir = await createTempDir();\n    const filePath = join(dir, \"empty.yml\");\n    await Bun.write(filePath, \"\");\n\n    const { stdout, stderr, exitCode } = await runCli([filePath]);\n\n    expect(exitCode).toBe(0);\n    expect(stdout).toContain(`Valid: ${filePath}`);\n    expect(stderr).toBe(\"\");\n  });\n});\n"
      },
