/**
 * YAML syntax validator with multi-document support and line-tracking error reporting.
 * Performs read-only structural analysis only; does not evaluate or execute YAML tags.
 */

export interface ValidationError {
  line: number;
  column: number;
  message: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

interface DocumentSegment {
  lines: string[];
  startLine: number;
}

/**
 * Validate a string as YAML syntax.
 * Handles multi-document YAML (--- separators).
 * Returns a ValidationResult with any syntax errors found.
 */
export function validateYaml(content: string): ValidationResult {
  if (content === "" || content.trim() === "") {
    return { valid: true, errors: [] };
  }

  const errors: ValidationError[] = [];
  const allLines = content.split("\n");

  checkControlCharacters(allLines, errors);

  const documents = splitDocuments(allLines);

  for (const doc of documents) {
    validateDocument(doc, errors);
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}

function checkControlCharacters(
  lines: string[],
  errors: ValidationError[]
): void {
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    for (let col = 0; col < line.length; col++) {
      const code = line.charCodeAt(col);
      // Control characters excluding tab (0x09), LF (0x0A), CR (0x0D)
      if (code < 0x20 && code !== 0x09 && code !== 0x0a && code !== 0x0d) {
        errors.push({
          line: i + 1,
          column: col + 1,
          message: `invalid control character (0x${code.toString(16).padStart(2, "0")})`,
        });
      }
    }
  }
}

function splitDocuments(lines: string[]): DocumentSegment[] {
  const documents: DocumentSegment[] = [];
  let currentLines: string[] = [];
  let currentStart = 0;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line === "---" || line === "--- ") {
      if (i > 0 || currentLines.length > 0) {
        if (currentLines.length > 0) {
          documents.push({ lines: currentLines, startLine: currentStart });
        }
        currentLines = [];
        currentStart = i + 1;
      } else {
        currentStart = i + 1;
      }
    } else if (line === "...") {
      if (currentLines.length > 0) {
        documents.push({ lines: currentLines, startLine: currentStart });
      }
      currentLines = [];
      currentStart = i + 1;
    } else {
      currentLines.push(line);
    }
  }

  if (currentLines.length > 0) {
    documents.push({ lines: currentLines, startLine: currentStart });
  }

  // Handle files with only document markers and no content
  if (documents.length === 0 && lines.length > 0) {
    return [{ lines: [], startLine: 0 }];
  }

  return documents;
}

function validateDocument(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  if (doc.lines.length === 0) return;
  if (doc.lines.every((l) => l.trim() === "")) return;

  checkTabIndentation(doc, errors);
  checkQuotedStrings(doc, errors);
  checkFlowCollections(doc, errors);
  checkIndentationConsistency(doc, errors);
  checkDuplicateKeys(doc, errors);
  checkMappingAndSequenceSyntax(doc, errors);
}

function checkTabIndentation(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "") continue;

    const leadingWhitespace = line.match(/^(\s*)/)?.[1] ?? "";
    if (leadingWhitespace.includes("\t")) {
      const tabCol = leadingWhitespace.indexOf("\t");
      errors.push({
        line: doc.startLine + i + 1,
        column: tabCol + 1,
        message: "tab character in indentation (use spaces instead)",
      });
    }

    if (/^ +\t/.test(leadingWhitespace) || /^\t+ /.test(leadingWhitespace)) {
      // Already reported tab above, skip duplicate
      if (!leadingWhitespace.includes("\t") || errors.length === 0) {
      }
    }
  }
}

function checkQuotedStrings(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "" || line.trim().startsWith("#")) continue;

    let inDouble = false;
    let inSingle = false;
    for (let col = 0; col < line.length; col++) {
      const ch = line[col];
      if (ch === "#" && !inDouble && !inSingle) {
        // Only a comment if preceded by whitespace or at start of line
        if (col === 0 || line[col - 1] === " ") {
          break;
        }
      }
      if (ch === '"' && !inSingle) {
        if (!inDouble) {
          inDouble = true;
        } else if (col > 0 && line[col - 1] === "\\") {
          // Backslash-escaped double quote stays in string
        } else {
          inDouble = false;
        }
      } else if (ch === "'" && !inDouble) {
        if (!inSingle) {
          inSingle = true;
        } else if (col + 1 < line.length && line[col + 1] === "'") {
          // Doubled single quote is YAML's escape for literal quote inside single-quoted strings
          col++;
        } else {
          inSingle = false;
        }
      }
    }

    if (inDouble) {
      errors.push({
        line: doc.startLine + i + 1,
        column: 1,
        message: "unclosed double quote",
      });
    }

    if (inSingle) {
      errors.push({
        line: doc.startLine + i + 1,
        column: 1,
        message: "unclosed single quote",
      });
    }
  }
}

function checkFlowCollections(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  const stack: { char: string; line: number; column: number }[] = [];

  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "" || line.trim().startsWith("#")) continue;

    let inSingle = false;
    let inDouble = false;

    for (let col = 0; col < line.length; col++) {
      const ch = line[col];

      if (ch === '"' && !inSingle) {
        if (!inDouble) {
          inDouble = true;
        } else if (col > 0 && line[col - 1] === "\\") {
          // Backslash-escaped, stays in double-quoted string
        } else {
          inDouble = false;
        }
        continue;
      }
      if (ch === "'" && !inDouble) {
        if (!inSingle) {
          inSingle = true;
        } else if (col + 1 < line.length && line[col + 1] === "'") {
          col++;
        } else {
          inSingle = false;
        }
        continue;
      }

      if (inSingle || inDouble) continue;

      if (ch === "#" && (col === 0 || line[col - 1] === " ")) break;

      if (ch === "[" || ch === "{") {
        stack.push({
          char: ch,
          line: doc.startLine + i + 1,
          column: col + 1,
        });
      } else if (ch === "]" || ch === "}") {
        const expected = ch === "]" ? "[" : "{";
        if (stack.length === 0 || stack[stack.length - 1].char !== expected) {
          errors.push({
            line: doc.startLine + i + 1,
            column: col + 1,
            message: `unexpected closing '${ch}' without matching '${expected}'`,
          });
        } else {
          stack.pop();
        }
      }
    }
  }

  for (const open of stack) {
    const closing = open.char === "[" ? "]" : "}";
    errors.push({
      line: open.line,
      column: open.column,
      message: `unclosed '${open.char}' (expected '${closing}')`,
    });
  }
}

function getIndent(line: string): number {
  const match = line.match(/^( *)/);
  return match ? match[1].length : 0;
}

function checkIndentationConsistency(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  let prevIndent = 0;
  let indentUnit = 0;
  let firstIndentLine = -1;

  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "" || line.trim().startsWith("#")) continue;
    // Skip lines with tabs (already reported by checkTabIndentation)
    if (/^\s*\t/.test(line)) continue;

    const indent = getIndent(line);

    if (indent > prevIndent) {
      const increase = indent - prevIndent;
      if (indentUnit === 0) {
        indentUnit = increase;
        firstIndentLine = i;
      } else if (increase !== indentUnit && increase % indentUnit !== 0) {
        errors.push({
          line: doc.startLine + i + 1,
          column: 1,
          message: `inconsistent indentation (expected multiple of ${indentUnit} spaces, found ${increase} space increase)`,
        });
      }
    }

    prevIndent = indent;
  }
}

function checkDuplicateKeys(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  const keysByIndent = new Map<number, Set<string>>();
  let prevIndent = -1;

  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "" || line.trim().startsWith("#")) continue;
    if (/^\s*\t/.test(line)) continue;

    const indent = getIndent(line);
    const trimmed = line.trim();

    if (indent < prevIndent) {
      for (const [level] of keysByIndent) {
        if (level > indent) {
          keysByIndent.delete(level);
        }
      }
    }
    if (indent > prevIndent) {
      keysByIndent.delete(indent);
    }

    if (!trimmed.startsWith("-") && !trimmed.startsWith("[") && !trimmed.startsWith("{")) {
      const keyMatch = extractMappingKey(trimmed);
      if (keyMatch !== null) {
        if (!keysByIndent.has(indent)) {
          keysByIndent.set(indent, new Set());
        }
        const keysAtLevel = keysByIndent.get(indent)!;
        if (keysAtLevel.has(keyMatch)) {
          errors.push({
            line: doc.startLine + i + 1,
            column: 1,
            message: `duplicate key '${keyMatch}'`,
          });
        } else {
          keysAtLevel.add(keyMatch);
        }
      }
    }

    prevIndent = indent;
  }
}

function extractMappingKey(trimmed: string): string | null {
  if (trimmed.startsWith('"')) {
    const endQuote = findClosingDoubleQuote(trimmed, 1);
    if (endQuote > 0 && endQuote + 1 < trimmed.length && trimmed[endQuote + 1] === ":") {
      return trimmed.substring(1, endQuote);
    }
    return null;
  }
  if (trimmed.startsWith("'")) {
    const endQuote = findClosingSingleQuote(trimmed, 1);
    if (endQuote > 0 && endQuote + 1 < trimmed.length && trimmed[endQuote + 1] === ":") {
      return trimmed.substring(1, endQuote);
    }
    return null;
  }

  const colonIndex = trimmed.indexOf(":");
  if (colonIndex > 0) {
    const afterColon = trimmed[colonIndex + 1];
    // Colon must be followed by space, end of line, or nothing for a valid mapping
    if (afterColon === undefined || afterColon === " " || afterColon === "\t") {
      return trimmed.substring(0, colonIndex).trim();
    }
  }

  return null;
}

function findClosingDoubleQuote(str: string, start: number): number {
  for (let i = start; i < str.length; i++) {
    if (str[i] === '"' && str[i - 1] !== "\\") {
      return i;
    }
  }
  return -1;
}

function findClosingSingleQuote(str: string, start: number): number {
  for (let i = start; i < str.length; i++) {
    if (str[i] === "'") {
      if (i + 1 < str.length && str[i + 1] === "'") {
        i++;
        continue;
      }
      return i;
    }
  }
  return -1;
}

function checkMappingAndSequenceSyntax(
  doc: DocumentSegment,
  errors: ValidationError[]
): void {
  const contextByIndent = new Map<number, "mapping" | "sequence">();
  let prevIndent = -1;

  for (let i = 0; i < doc.lines.length; i++) {
    const line = doc.lines[i];
    if (line.trim() === "" || line.trim().startsWith("#")) continue;
    if (/^\s*\t/.test(line)) continue;

    const indent = getIndent(line);
    const trimmed = line.trim();

    if (indent < prevIndent) {
      for (const [level] of contextByIndent) {
        if (level > indent) contextByIndent.delete(level);
      }
    }
    if (indent > prevIndent) {
      contextByIndent.delete(indent);
    }

    const isSequenceItem = trimmed.startsWith("- ") || trimmed === "-";

    // Bare dash followed by non-space content (e.g., "-foo") is malformed
    if (
      trimmed.startsWith("-") &&
      !isSequenceItem &&
      trimmed.length > 1 &&
      trimmed[1] !== " "
    ) {
      errors.push({
        line: doc.startLine + i + 1,
        column: indent + 1,
        message:
          "malformed block sequence entry (expected space after '-')",
      });
      prevIndent = indent;
      continue;
    }

    const isMapping =
      !isSequenceItem && extractMappingKey(trimmed) !== null;
    const isFlowLine = trimmed.startsWith("[") || trimmed.startsWith("{");

    let lineType: "mapping" | "sequence" | null = null;
    if (isSequenceItem) lineType = "sequence";
    else if (isMapping) lineType = "mapping";

    if (lineType !== null) {
      const existingCtx = contextByIndent.get(indent);
      if (existingCtx !== undefined && existingCtx !== lineType) {
        if (lineType === "sequence") {
          errors.push({
            line: doc.startLine + i + 1,
            column: indent + 1,
            message: "block sequence entry found in mapping context",
          });
        } else {
          errors.push({
            line: doc.startLine + i + 1,
            column: indent + 1,
            message: "mapping entry found in sequence context",
          });
        }
      } else {
        contextByIndent.set(indent, lineType);
      }
    } else if (!isFlowLine) {
      // Line has no colon separator and is not a sequence entry or flow collection;
      // if a mapping context is already established at this indent, the line is invalid
      const existingCtx = contextByIndent.get(indent);
      if (existingCtx === "mapping") {
        errors.push({
          line: doc.startLine + i + 1,
          column: indent + 1,
          message:
            "expected mapping key-value pair (missing ':' separator)",
        });
      }
    }

    prevIndent = indent;
  }
}

