/**
 * CLI entry point for YAML file validation.
 * Accepts one or more file paths as arguments and validates each for YAML syntax correctness.
 * Success messages go to stdout; errors go to stderr.
 * Exit code 0 if all files valid, 1 otherwise.
 */

import { validateYaml } from "./yaml-parser";

const USAGE = `Usage: bun run validate-yaml <file1.yml> [file2.yml] [...]

Validates YAML files for syntax correctness.

Arguments:
  file1.yml    Path to a YAML file to validate (one or more required)`;

async function main(): Promise<void> {
  const filePaths = process.argv.slice(2);

  if (filePaths.length === 0) {
    console.error(USAGE);
    process.exit(1);
  }

  let hasErrors = false;

  for (const filePath of filePaths) {
    const file = Bun.file(filePath);
    const exists = await file.exists();

    if (!exists) {
      console.error(`Error: ${filePath} - file not found`);
      hasErrors = true;
      continue;
    }

    const content = await file.text();
    const result = validateYaml(content);

    if (result.valid) {
      console.log(`Valid: ${filePath}`);
    } else {
      for (const error of result.errors) {
        console.error(
          `Error: ${filePath}:${error.line}:${error.column} - ${error.message}`
        );
      }
      hasErrors = true;
    }
  }

  process.exit(hasErrors ? 1 : 0);
}

main();

import { describe, expect, test } from "bun:test";
import { validateYaml } from "./yaml-parser";
import type { ValidationResult } from "./yaml-parser";

describe("validateYaml", () => {
  describe("valid YAML", () => {
    test("simple mapping", () => {
      const result = validateYaml("key: value");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("nested mapping", () => {
      const result = validateYaml(
        "parent:\n  child: value\n  other: 42"
      );
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("deeply nested mapping", () => {
      const result = validateYaml(
        "a:\n  b:\n    c: deep"
      );
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("block sequence", () => {
      const result = validateYaml("- item1\n- item2");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("sequence under a mapping key", () => {
      const result = validateYaml(
        "items:\n  - one\n  - two\n  - three"
      );
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("multi-document with --- separators", () => {
      const result = validateYaml("---\nfoo: 1\n---\nbar: 2");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("multi-document with ... end marker", () => {
      const result = validateYaml("foo: 1\n...\nbar: 2");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("empty content", () => {
      const result = validateYaml("");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("whitespace-only content", () => {
      const result = validateYaml("   \n  \n");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("double-quoted string value", () => {
      const result = validateYaml('key: "hello world"');
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("single-quoted string value", () => {
      const result = validateYaml("key: 'hello world'");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("double-quoted key", () => {
      const result = validateYaml('"my key": value');
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("single-quoted key with escaped quote inside", () => {
      const result = validateYaml("key: 'it''s fine'");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("double-quoted value with escaped quote inside", () => {
      const result = validateYaml('key: "say \\"hello\\""');
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("flow sequence", () => {
      const result = validateYaml("items: [a, b, c]");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("flow mapping", () => {
      const result = validateYaml("data: {x: 1, y: 2}");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("comment lines", () => {
      const result = validateYaml("# this is a comment\nkey: value");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("inline comment after value", () => {
      const result = validateYaml("key: value # a comment");
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("boolean and numeric values", () => {
      const result = validateYaml(
        "enabled: true\ncount: 42\nratio: 3.14"
      );
      expect(result).toEqual({ valid: true, errors: [] });
    });

    test("only document markers", () => {
      const result = validateYaml("---\n...");
      expect(result).toEqual({ valid: true, errors: [] });
    });
  });

  describe("invalid YAML - tab indentation", () => {
    test("tab in indentation", () => {
      const result = validateYaml("key:\n\tvalue: bad");
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      const tabError = result.errors.find((e) =>
        e.message.includes("tab")
      );
      expect(tabError).toBeDefined();
      expect(tabError!.line).toBe(2);
    });
  });

  describe("invalid YAML - unclosed quotes", () => {
    test("unclosed double quote", () => {
      const result = validateYaml('key: "unclosed');
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) =>
        e.message.includes("unclosed double quote")
      );
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(1);
    });

    test("unclosed single quote", () => {
      const result = validateYaml("key: 'unclosed");
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) =>
        e.message.includes("unclosed single quote")
      );
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(1);
    });
  });

  describe("invalid YAML - flow collection brackets", () => {
    test("unclosed square bracket", () => {
      const result = validateYaml("items: [a, b");
      expect(result.valid).toBe(false);
      const bracketError = result.errors.find((e) =>
        e.message.includes("unclosed '['")
      );
      expect(bracketError).toBeDefined();
      expect(bracketError!.line).toBeGreaterThan(0);
    });

    test("unclosed curly brace", () => {
      const result = validateYaml("data: {a: 1");
      expect(result.valid).toBe(false);
      const braceError = result.errors.find((e) =>
        e.message.includes("unclosed '{'")
      );
      expect(braceError).toBeDefined();
      expect(braceError!.line).toBeGreaterThan(0);
    });

    test("unexpected closing bracket", () => {
      const result = validateYaml("items: ]");
      expect(result.valid).toBe(false);
      const bracketError = result.errors.find((e) =>
        e.message.includes("unexpected closing")
      );
      expect(bracketError).toBeDefined();
    });
  });

  describe("invalid YAML - indentation consistency", () => {
    test("inconsistent indentation levels", () => {
      const result = validateYaml("a:\n  b: 1\n   c: 2");
      expect(result.valid).toBe(false);
      const indentError = result.errors.find((e) =>
        e.message.includes("inconsistent indentation")
      );
      expect(indentError).toBeDefined();
      expect(indentError!.line).toBeGreaterThan(0);
    });
  });

  describe("invalid YAML - duplicate keys", () => {
    test("duplicate keys at same level", () => {
      const result = validateYaml("name: Alice\nage: 30\nname: Bob");
      expect(result.valid).toBe(false);
      const dupError = result.errors.find((e) =>
        e.message.includes("duplicate key")
      );
      expect(dupError).toBeDefined();
      expect(dupError!.line).toBe(3);
      expect(dupError!.message).toContain("name");
    });

    test("same key at different indent levels is valid", () => {
      const result = validateYaml(
        "parent:\n  name: child\nname: top"
      );
      expect(result.valid).toBe(true);
    });
  });

  describe("invalid YAML - mapping and sequence syntax", () => {
    test("bare dash without space (malformed sequence)", () => {
      const result = validateYaml("-foo");
      expect(result.valid).toBe(false);
      const seqError = result.errors.find((e) =>
        e.message.includes("malformed block sequence")
      );
      expect(seqError).toBeDefined();
      expect(seqError!.line).toBeGreaterThan(0);
    });

    test("mixing sequence and mapping at same indent", () => {
      const result = validateYaml("- item1\nkey: value");
      expect(result.valid).toBe(false);
      const mixError = result.errors.find(
        (e) =>
          e.message.includes("mapping entry found in sequence context") ||
          e.message.includes("block sequence entry found in mapping context")
      );
      expect(mixError).toBeDefined();
    });

    test("missing colon in mapping context", () => {
      const result = validateYaml("key: value\njust_a_string");
      expect(result.valid).toBe(false);
      const colonError = result.errors.find((e) =>
        e.message.includes("missing ':'")
      );
      expect(colonError).toBeDefined();
      expect(colonError!.line).toBe(2);
    });
  });

  describe("invalid YAML - control characters", () => {
    test("control character in content", () => {
      const result = validateYaml("key: val\x01ue");
      expect(result.valid).toBe(false);
      const ctrlError = result.errors.find((e) =>
        e.message.includes("control character")
      );
      expect(ctrlError).toBeDefined();
      expect(ctrlError!.line).toBe(1);
    });
  });

  describe("multi-document error line tracking", () => {
    test("error in second document reports original file line number", () => {
      const content = "---\nfoo: 1\n---\nbad: [unclosed";
      const result = validateYaml(content);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      // "bad: [unclosed" is on line 4 of the original file
      const bracketError = result.errors.find((e) =>
        e.message.includes("unclosed '['")
      );
      expect(bracketError).toBeDefined();
      expect(bracketError!.line).toBe(4);
    });

    test("error in third document reports correct line number", () => {
      const content = "---\na: 1\n---\nb: 2\n---\nc: 'unclosed";
      const result = validateYaml(content);
      expect(result.valid).toBe(false);
      const quoteError = result.errors.find((e) =>
        e.message.includes("unclosed single quote")
      );
      expect(quoteError).toBeDefined();
      expect(quoteError!.line).toBe(6);
    });
  });

  describe("error result shape", () => {
    test("all errors have line > 0 and a descriptive message", () => {
      const inputs = [
        'key: "unclosed',
        "key:\n\tval: bad",
        "items: [a, b",
        "name: Alice\nname: Bob",
