// HYP-002: Test whether Bun.YAML.parse() can reliably detect common YAML syntax errors
// (as an alternative to a hand-written validator)

const testCases = [
  {
    name: "Valid simple mapping",
    yaml: "key: value\nother: data",
    expectError: false,
  },
  {
    name: "Valid nested mapping",
    yaml: "parent:\n  child: value\n  another: 42",
    expectError: false,
  },
  {
    name: "Valid block sequence",
    yaml: "- item1\n- item2\n- item3",
    expectError: false,
  },
  {
    name: "Valid multi-document",
    yaml: "---\nfoo: 1\n---\nbar: 2",
    expectError: false,
  },
  {
    name: "Valid empty",
    yaml: "",
    expectError: false,
  },
  {
    name: "Valid quoted strings",
    yaml: 'name: "hello world"\nsingle: \'quoted\'',
    expectError: false,
  },
  {
    name: "Invalid: unclosed double quote",
    yaml: 'key: "unclosed value\nother: data',
    expectError: true,
  },
  {
    name: "Invalid: unclosed single quote",
    yaml: "key: 'unclosed value\nother: data",
    expectError: true,
  },
  {
    name: "Invalid: unclosed bracket [",
    yaml: "items: [a, b, c\nkey: value",
    expectError: true,
  },
  {
    name: "Invalid: unclosed brace {",
    yaml: "data: {a: 1, b: 2\nkey: value",
    expectError: true,
  },
  {
    name: "Invalid: tab in indentation",
    yaml: "key: value\n\tchild: data",
    expectError: true,  // YAML spec forbids tabs for indentation
  },
  {
    name: "Invalid: bad indentation (de-indent mid-mapping)",
    yaml: "parent:\n    child: value\n  bad: indent",
    expectError: true,
  },
  {
    name: "Invalid: colon without space in mapping",
    yaml: "key:value",
    expectError: true,
  },
  {
    name: "Invalid: multiple colons",
    yaml: "key: val: ue",
    expectError: true,
  },
  {
    name: "Duplicate keys (same level)",
    yaml: "key: value1\nkey: value2",
    expectError: true,  // debatable - YAML spec says should warn, most parsers accept silently
  },
  {
    name: "Invalid: mapping after sequence indicator",
    yaml: "- item\n  key: value\n- item2\n key: bad",
    expectError: true,
  },
  {
    name: "Valid: flow mapping",
    yaml: "data: {a: 1, b: 2, c: 3}",
    expectError: false,
  },
  {
    name: "Valid: complex nested",
    yaml: "database:\n  host: localhost\n  port: 5432\n  credentials:\n    user: admin\n    password: secret\nservers:\n  - name: web1\n    port: 80\n  - name: web2\n    port: 8080",
    expectError: false,
  },
];

let passed = 0;
let failed = 0;
let unexpected = 0;

for (const tc of testCases) {
  try {
    const result = Bun.YAML.parse(tc.yaml);
    if (tc.expectError) {
      console.log(`UNEXPECTED PASS: "${tc.name}" - Expected error but parsed OK. Result: ${JSON.stringify(result)}`);
      unexpected++;
    } else {
      console.log(`OK: "${tc.name}" - Parsed successfully`);
      passed++;
    }
  } catch (e: any) {
    if (!tc.expectError) {
      console.log(`UNEXPECTED ERROR: "${tc.name}" - ${e.message}`);
      unexpected++;
    } else {
      const hasLine = "line" in e || "originalLine" in e;
      console.log(`OK: "${tc.name}" - Error caught: ${e.message}${hasLine ? ` (has line info)` : " (NO line info)"}`);
      passed++;
    }
  }
}

console.log(`\n=== RESULTS ===`);
console.log(`Passed: ${passed}`);
console.log(`Unexpected: ${unexpected}`);
console.log(`Total: ${testCases.length}`);
